import 'package:cloud_firestore/cloud_firestore.dart';\nimport 'package:firebase_auth/firebase_auth.dart';\nimport '../models/ai_tool.dart';\nimport '../models/user_model.dart';\n\nclass FirebaseService {\n  static final FirebaseService _instance = FirebaseService._internal();\n\n  factory FirebaseService() {\n    return _instance;\n  }\n\n  FirebaseService._internal();\n\n  final FirebaseAuth _auth = FirebaseAuth.instance;\n  final FirebaseFirestore _firestore = FirebaseFirestore.instance;\n\n  User? getCurrentUser() {\n    return _auth.currentUser;\n  }\n\n  Stream<User?> authStateChanges() {\n    return _auth.authStateChanges();\n  }\n\n  Future<void> createUserDocument(User user) async {\n    try {\n      final userModel = UserModel(\n        uid: user.uid,\n        email: user.email ?? '',\n        displayName: user.displayName,\n        photoUrl: user.photoURL,\n        createdAt: DateTime.now(),\n      );\n      await _firestore.collection('users').doc(user.uid).set(userModel.toJson());\n    } catch (e) {\n      print('Error creating user document: $e');\n    }\n  }\n\n  Future<List<AITool>> getAllTools() async {\n    try {\n      final snapshot = await _firestore.collection('ai_tools').get();\n      return snapshot.docs.map((doc) => AITool.fromFirestore(doc)).toList();\n    } catch (e) {\n      print('Error getting all tools: $e');\n      return [];\n    }\n  }\n\n  Future<List<AITool>> getToolsByCategory(String category) async {\n    try {\n      final snapshot = await _firestore.collection('ai_tools').where('category', isEqualTo: category).get();\n      return snapshot.docs.map((doc) => AITool.fromFirestore(doc)).toList();\n    } catch (e) {\n      return [];\n    }\n  }\n\n  Future<List<AITool>> getTrendingTools() async {\n    try {\n      final snapshot = await _firestore.collection('ai_tools').where('isTrending', isEqualTo: true).limit(10).get();\n      return snapshot.docs.map((doc) => AITool.fromFirestore(doc)).toList();\n    } catch (e) {\n      return [];\n    }\n  }\n\n  Future<AITool?> getToolById(String toolId) async {\n    try {\n      final doc = await _firestore.collection('ai_tools').doc(toolId).get();\n      if (doc.exists) {\n        return AITool.fromFirestore(doc);\n      }\n      return null;\n    } catch (e) {\n      return null;\n    }\n  }\n\n  Future<List<AITool>> searchTools(String query) async {\n    try {\n      final snapshot = await _firestore.collection('ai_tools').get();\n      final tools = snapshot.docs.map((doc) => AITool.fromFirestore(doc)).toList();\n      return tools.where((tool) => tool.name.toLowerCase().contains(query.toLowerCase()) || tool.description.toLowerCase().contains(query.toLowerCase())).toList();\n    } catch (e) {\n      return [];\n    }\n  }\n\n  Future<void> addFavorite(String userId, String toolId) async {\n    try {\n      await _firestore.collection('users').doc(userId).update({\n        'favoriteToolIds': FieldValue.arrayUnion([toolId]),\n      });\n    } catch (e) {\n      print('Error: $e');\n    }\n  }\n\n  Future<void> removeFavorite(String userId, String toolId) async {\n    try {\n      await _firestore.collection('users').doc(userId).update({\n        'favoriteToolIds': FieldValue.arrayRemove([toolId]),\n      });\n    } catch (e) {\n      print('Error: $e');\n    }\n  }\n}\n